<template>
    <HsxDrawer v-model="visible" :title="`${businessName || '设备需求'}目录`" subtitle="先校验并预览，再明确确认替换；目录不是实际库存或报价。" size="md" :body-loading="loading" :confirm-loading="saving" show-footer confirm-text="确认替换当前业务目录" :confirm-disabled="!previewReady || loading || !!fileError || !confirmed" @confirm="save">
        <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon class="lead-error-banner" />
        <el-alert v-if="!loading && !previewSupported" title="当前服务器未确认支持无写入预览；为避免误替换，导入已禁用，请先更新配套后端并刷新目录。" type="warning" :closable="false" show-icon class="lead-error-banner" />
        <el-alert :title="businessType ? `范围：仅本站「${businessName || businessType}」需求目录，不改其他业务，不覆盖已有线索或商户能力记录。` : '范围：仅本站通用设备需求目录，不修改已录入线索。'" type="info" show-icon :closable="false" class="lead-banner" />
        <div class="lead-actions"><el-upload accept=".xlsx,.csv,.json" :auto-upload="false" :show-file-list="false" :on-change="chooseFile" :disabled="saving || previewing || !previewSupported"><el-button>选择 Excel / CSV / JSON</el-button></el-upload><el-button @click="downloadTemplate">下载三级目录模板</el-button><el-button :loading="loading" :disabled="saving || previewing" @click="load">刷新当前目录</el-button></div>
        <el-collapse class="catalog-help"><el-collapse-item title="支持格式与校验范围" name="format"><p class="lead-muted">xlsx原文件最多2 MB，仅支持一个工作表、纯文本与最多5000项；不接受公式或外链。CSV / JSON最多1 MB。三级列为“一级分类、二级分类、三级分类”，名称列可用“名称”或“型号”，ID、品牌、别名可选。CSV请用UTF-8；JSON使用items数组。所有内容由服务器完整校验，一项有误不会部分保存。</p><p class="lead-muted">文件尚未提供时继续使用当前目录；不会生成或导入虚构目录。模板不含示例业务数据。</p></el-collapse-item></el-collapse>
        <el-alert v-if="fileError" :title="fileError" type="error" show-icon :closable="false" class="lead-error-banner" />
        <section v-if="filename" class="catalog-pending"><div class="catalog-pending-head"><div><strong>待校验文件：{{ filename }}</strong><p class="lead-muted">{{ previewReady ? `已通过完整校验，共${previewItems.length}项，尚未保存。` : '仅已读取本地文件，尚未校验或保存。' }}</p></div><el-button :loading="previewing" :disabled="saving || !content || !!fileError" @click="preview">校验并预览</el-button></div><template v-if="previewReady"><HsxTable :columns="columns" :data="previewItems.slice(0,100)" row-key="id" empty-text="文件没有可导入项"><template #path="{row}">{{ (row.path || []).join(' / ') || row.category_name || '—' }}</template></HsxTable><p v-if="previewItems.length>100" class="lead-muted">预览前100项，确认后替换完整{{ previewItems.length }}项。</p><el-checkbox v-model="confirmed">我已核对{{ businessName || '当前业务' }}目录及{{ previewItems.length }}项内容，确认替换</el-checkbox></template></section>
        <section class="lead-form-section"><h3>当前目录 · {{ items.length }}项</h3><p class="lead-muted">{{ sourceLabel }}</p><el-input v-model="keyword" clearable placeholder="搜索名称、品牌或三级分类" style="margin:14px 0" /><HsxTable :columns="columns" :data="filtered.slice(0,100)" row-key="id" :empty-text="error ? '目录未读取，请重试' : '当前目录没有选项'"><template #path="{row}">{{ (row.path || []).join(' / ') || row.category_name || '—' }}</template></HsxTable><p v-if="filtered.length>100" class="lead-muted" style="margin-top:12px">匹配{{ filtered.length }}项，当前显示前100项。</p></section>
    </HsxDrawer>
</template>
<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { ElMessage, type UploadFile } from 'element-plus'
import HsxDrawer from '@/addon/hsx_components/components/HsxDrawer/index.vue'
import HsxTable from '@/addon/hsx_components/components/HsxTable/index.vue'
import { getCatalog, saveCatalog } from '../../api'
import { errorText, type Row } from '../../composables/useLeadUi'
const props = withDefaults(defineProps<{ modelValue:boolean; businessType?:string; businessName?:string }>(),{businessType:'',businessName:''})
const emit = defineEmits<{(e:'update:modelValue',value:boolean):void;(e:'changed'):void}>()
const visible=computed({get:()=>props.modelValue,set:value=>{if(!saving.value&&!previewing.value)emit('update:modelValue',value)}})
const items=ref<Row[]>([]),source=ref(''),loading=ref(false),saving=ref(false),previewing=ref(false),previewSupported=ref(false),error=ref(''),fileError=ref(''),content=ref(''),format=ref<'csv'|'json'|'xlsx'>('csv'),filename=ref(''),keyword=ref(''),previewItems=ref<Row[]>([]),previewReady=ref(false),confirmed=ref(false)
const filtered=computed(()=>items.value.filter(item=>[item.title,item.brand,item.category_name,...(item.path||[]),...(item.aliases||[])].join(' ').toLowerCase().includes(keyword.value.trim().toLowerCase())))
const sourceLabel=computed(()=>source.value==='configured'?'已保存的本站自定义目录':source.value==='business_config'?'当前业务可选目录；独立选项或已有设备目录，不代表库存或价格':source.value==='inventory'?'使用已同步库存中的型号作为需求选项；不代表现货':'使用已有常用目录及已同步型号，不代表库存或价格')
const columns=[{prop:'title',label:'名称 / 型号',minWidth:190},{prop:'path',label:'三级分类路径',slot:'path',minWidth:220},{prop:'id',label:'稳定ID',minWidth:150}]
let sequence=0,fileSequence=0
function clearPreview(){previewItems.value=[];previewReady.value=false;confirmed.value=false}
async function load(){const token=++sequence;loading.value=true;error.value='';previewSupported.value=false;try{const result=await getCatalog(props.businessType?{business_type:props.businessType}:{});if(token===sequence){items.value=result.data.items||[];source.value=result.data.source||'';previewSupported.value=result.data.supports_preview===true}}catch(cause){if(token===sequence)error.value=errorText(cause,'目录读取失败，请重试。')}finally{if(token===sequence)loading.value=false}}
async function chooseFile(file:UploadFile){const token=++fileSequence;content.value='';filename.value='';fileError.value='';clearPreview();if(!file.raw){fileError.value='无法读取文件，请重新选择';return}if(!/\.(xlsx|csv|json)$/i.test(file.name)){fileError.value='只支持xlsx、CSV或JSON文件';return}const xlsx=/\.xlsx$/i.test(file.name);if(file.raw.size>(xlsx?2:1)*1024*1024){fileError.value=xlsx?'Excel超过2 MB，请精简后重试':'文件超过1 MB，请精简后重试';return}try{let value='';if(xlsx){const bytes=new Uint8Array(await file.raw.arrayBuffer());let binary='';for(let offset=0;offset<bytes.length;offset+=8192)binary+=String.fromCharCode(...bytes.subarray(offset,offset+8192));value=btoa(binary)}else value=(await file.raw.text()).replace(/^\uFEFF/,'');if(token!==fileSequence)return;if(!value.trim()){fileError.value='文件内容为空，请检查后重试';return}content.value=value;filename.value=file.name;format.value=xlsx?'xlsx':/\.json$/i.test(file.name)?'json':'csv'}catch(cause){if(token===fileSequence)fileError.value=errorText(cause,'文件读取失败，请重新选择文件')}}
function payload(previewOnly:boolean){return{content:content.value,format:format.value,...(props.businessType?{business_type:props.businessType}:{}),preview:previewOnly}}
async function preview(){if(!content.value||saving.value||previewing.value||!previewSupported.value)return;const token=fileSequence;previewing.value=true;error.value='';clearPreview();try{const result=await saveCatalog(payload(true));if(token!==fileSequence||!visible.value)return;if(result.data?.preview!==true||!Array.isArray(result.data.items))throw new Error('服务器未返回有效预览，目录未确认保存，请核对配套后端');previewItems.value=result.data.items;previewReady.value=previewItems.value.length>0;if(!previewReady.value)error.value='文件中没有可导入项'}catch(cause){if(token===fileSequence)error.value=errorText(cause,'文件校验未通过；没有保存任何目录，请按提示修改文件')}finally{previewing.value=false}}
function downloadTemplate(){const url=URL.createObjectURL(new Blob(['\uFEFF一级分类,二级分类,三级分类,名称,id,品牌,别名\r\n'],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='三级需求目录导入模板.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function save(){if(!content.value||!previewReady.value||!confirmed.value||fileError.value||saving.value)return;saving.value=true;error.value='';try{await saveCatalog(payload(false));content.value='';filename.value='';clearPreview();emit('changed');await load();ElMessage.success(error.value?'目录已保存，重新读取失败，请刷新核对':`当前业务目录已保存，共${items.value.length}项`)}catch(cause){error.value=errorText(cause,'目录未确认保存，已保留文件和预览，请核对后重试')}finally{saving.value=false}}
watch(()=>[props.modelValue,props.businessType],()=>{if(props.modelValue){content.value='';filename.value='';fileError.value='';keyword.value='';clearPreview();void load()}else{sequence++;fileSequence++;loading.value=false}})
onBeforeUnmount(()=>{sequence++;fileSequence++})
</script>
<style scoped>.catalog-help{margin:14px 0}.catalog-pending{margin:16px 0;padding:16px 0;border-top:1px solid var(--el-border-color-lighter);border-bottom:1px solid var(--el-border-color-lighter)}.catalog-pending-head{display:flex;gap:12px;align-items:center;justify-content:space-between;margin-bottom:14px;flex-wrap:wrap}.catalog-pending :deep(.el-checkbox){height:auto;margin-top:14px;white-space:normal}.catalog-pending :deep(.el-checkbox__label){white-space:normal}</style>
